function sql(value) {
  if (value === undefined || value === null || String(value).trim() === '') return 'NULL';
  return "'" + String(value).replace(/'/g, "''") + "'";
}

const input = $json.body || $json;
const assetId = String(input.assetId || '').trim();
const reviewNotes = String(input.reviewNotes || 'Rejected via Asset Review API').trim();
let reviewMetadata = null;
try {
  const parsed = JSON.parse(reviewNotes);
  if (parsed && typeof parsed === 'object' && parsed.contractVersion === 'publication-quality-review-v1') reviewMetadata = parsed;
} catch {}
const baseUrl = String(input.baseUrl || 'http://192.168.0.194:9000').replace(/[/]$/, '');

if (!assetId) {
  throw new Error('Missing required field: assetId');
}

return [{
  json: {
    assetId,
    assetIdSql: sql(assetId),
    reviewNotes,
    reviewNotesSql: sql(reviewNotes),
    reviewNotesJsonSql: sql(JSON.stringify(reviewNotes)),
    reviewMetadataJsonSql: sql(JSON.stringify(reviewMetadata)),
    baseUrl
  }
}];

const params = $('Normalize Reject Request').first().json;
const rejected = $input.first().json;

if (!rejected || !rejected.asset_id) {
  return [{
    json: {
      rejected: false,
      assetId: params.assetId,
      reason: 'Asset not found, already canonical, or rejection failed'
    }
  }];
}

return [{
  json: {
    rejected: true,
    assetId: rejected.asset_id,
    avatar: rejected.avatar,
    scene: rejected.scene,
    assetType: rejected.asset_type,
    url: `${params.baseUrl}/${rejected.bucket}/${rejected.object_path}`,
    bucket: rejected.bucket,
    objectPath: rejected.object_path,
    mimeType: rejected.mime_type,
    status: rejected.status,
    sha256: rejected.sha256,
    canonicalGroup: rejected.canonical_group,
    reviewNotes: rejected.review_notes,
    createdAt: rejected.created_at
  }
}];
